question:
The radius $r$ of a circle inscribed within three mutually externally tangent circles of radii $a$, $b$ and $c$ is given by
\[\frac{1}{r} = \frac{1}{a} + \frac{1}{b} + \frac{1}{c} + 2 \sqrt{\frac{1}{ab} + \frac{1}{ac} + \frac{1}{bc}}.\]What is the value of $r$ when $a = 4$, $b = 9$ and $c = 36$?

[asy]
unitsize(0.15 cm);

pair A, B, C, P;
real r = 1.86308;

A = (0,0);
B = (25,0);
C = intersectionpoint(arc(A,22,0,180),arc(B,27,0,180));
P = intersectionpoint(arc(A,10 + r,0,180),arc(B,15 + r,0,180));

draw(Circle(A,10));
draw(Circle(B,15));
draw(Circle(C,12));
draw(Circle(P,r));
draw(A--(A + (0,-10)));
draw(B--(B + (15,0)));
draw(C--(C + (0,12)));
draw(P--(P + (r,0)));

label("$a$", A + (0,-10)/2, W);
label("$b$", B + (15,0)/2, S);
label("$c$", C + (0,12)/2, W);
label("$r$", P + (r,0), E);
[/asy]

An ant moves on the following lattice, beginning at the dot labeled $A$. Each minute he moves to one of the dots neighboring the dot he was at, choosing from among its neighbors at random. What is the probability that after 5 minutes he is at the dot labeled $B$? [asy]
draw((-2,0)--(2,0));
draw((0,-2)--(0,2));
draw((1,1)--(1,-1)--(-1,-1)--(-1,1)--cycle);
dot((0,0)); dot((1,0)); dot((2,0)); dot((-1,0)); dot((-2,0)); dot((0,1)); dot((0,2)); dot((0,-1)); dot((0,-2)); dot((1,1)); dot((1,-1)); dot((-1,-1)); dot((-1,1));
label("$A$",(0,0),SW);
label("$B$",(0,1),NE);
[/asy]

Two of the vertices of a regular octahedron are to be chosen at random. What is the probability that they will be the endpoints of an edge of the octahedron? Express your answer as a common fraction. [asy]
size(150);
pair A, B, C, D, E, F;
A=(1,1);
B=(-1,-1);
C=(0,6);
D=(0,-6);
E=(6, 0);
F=(-6,0);
draw(C--F--D--E--C--B--F);
draw(D--B--E);
draw(F--A--C, dashed);
draw(D--A--E, dashed);
[/asy]

Quadrilateral $ABCD$ is a square. A circle with center $D$ has arc $AEC$. A circle with center $B$ has arc $AFC$. If $AB = 2$ cm, what is the total number of square centimeters in the football-shaped area of regions II and III combined? Express your answer as a decimal to the nearest tenth.

[asy]
path a=(7,13)..(0,0)--(20,20)..cycle;
path b=(13,7)..(0,0)--(20,20)..cycle;
draw(a);
draw(b);
dot((8.6,3.5));
label("F",(8.6,3.5),SE);
label("E",(11.4,16.5),NW);
dot((11.4,16.5));
draw((0,0)--(20,0)--(20,20)--(0,20)--cycle);
label("$A$",(0,0),SW);
label("$B$",(0,20),NW);
label("$C$",(20,20),NE);
label("$D$",(20,0),SE);
label("I",(2,19),S);
label("II",(9,13),S);
label("III",(11,7),N);
label("IV",(18,1),N);
[/asy]

Find the ratio of the area of $\triangle BCX$ to the area of $\triangle ACX$ in the diagram if $CX$ bisects $\angle ACB$. Express your answer as a common fraction. [asy]
import markers;

real t=27/(27+30);
pair A=(-15.57,0);
pair B=(8.43,0);
pair C=(0,25.65);
pair X=t*A+(1-t)*B;

draw(C--A--B--C--X);

label("$A$",A,SW);
label("$B$",B,E);
label("$C$",C,N);
label("$X$",X,NE);

//markangle(n=1,radius=15,A,C,X,marker(markinterval(stickframe(n=1),true)));
//markangle(n=1,radius=15,X,C,B,marker(markinterval(stickframe(n=1),true)));

label("$24$",.5*(B+A),S);
