draw((0,0)--(2,0)--(2,2)--(0,2)--cycle);
draw((0,0)--(2,1));
draw((0,0)--(1,2));
label("$A$", (0,0), SW);
label("$B$", (0,2), NW);
label("$C$", (2,2), NE);
label("$D$", (2,0), SE);
